messages.content:
 این کد HTML یک بازی Snake زیبا با پس‌زمینه تیره و گرید سبز ایجاد می‌کند. مار به صورت خودکار حرکت می‌کند و کاربر می‌تواند با کلیدهای جهت‌نما مسیر را تغییر دهد. بیایید کد را تکمیل کنم:

```html
<!DOCTYPE html>
<html lang="fa" dir="rtl">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>مار متحرک</title>
    <style>
        * { margin: 0; padding: 0; box-sizing: border-box; }
        body {
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
            height: 100vh;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            overflow: hidden;
        }
        h1 {
            color: #00ff88;
            margin-bottom: 20px;
            text-shadow: 0 0 20px rgba(0,255,136,0.3);
            font-size: 2rem;
        }
        #gameContainer {
            position: relative;
            border-radius: 16px;
            box-shadow: 0 0 40px rgba(0,255,136,0.1), 0 20px 60px rgba(0,0,0,0.5);
            overflow: hidden;
            border: 2px solid rgba(0,255,136,0.2);
        }
        canvas {
            display: block;
            background: #0f0f1e;
        }
        .info {
            color: #888;
            margin-top: 15px;
            font-size: 0.9rem;
        }
    </style>
</head>
<body>
    <h1>🐍 مار متحرک</h1>
    <div id="gameContainer">
        <canvas id="gameCanvas" width="800" height="600"></canvas>
    </div>
    <div class="info">با کلیدهای جهت‌نما می‌توانید مسیر را تغییر دهید</div>

    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        const gridSize = 20;
        const tileCountX = canvas.width / gridSize;
        const tileCountY = canvas.height / gridSize;

        let snake = [
            {x: 5, y: 15},
            {x: 4, y: 15},
            {x: 3, y: 15},
            {x: 2, y: 15},
            {x: 1, y: 15}
        ];

        let dx = 1;
        let dy = 0;
        let speed = 100; // milliseconds
        let lastTime = 0;

        // Draw grid background
        function drawGrid() {
            ctx.strokeStyle = 'rgba(0, 255, 136, 0.05)';
            ctx.lineWidth = 1;
            for(let i = 0; i <= tileCountX; i++) {
                ctx.beginPath();
                ctx.moveTo(i * gridSize, 0);
                ctx.lineTo(i * gridSize, canvas.height);
                ctx.stroke();
            }
            for(let i = 0; i <= tileCountY; i++) {
                ctx.beginPath();
                ctx.moveTo(0, i * gridSize);
                ctx.lineTo(canvas.width, i * gridSize);
                ctx.stroke();
            }
        }

        // Draw snake
        function drawSnake() {
            snake.forEach((segment, index) => {
                const x = segment.x * gridSize;
                const y = segment.y * gridSize;

                // Gradient for body
                const gradient = ctx.createRadialGradient(
                    x + gridSize/2, y + gridSize/2, 2,
                    x + gridSize/2, y + gridSize/2, gridSize/2
                );

                if(index === 0) {
                    // Head
                    gradient.addColorStop(0, '#00ff88');
                    gradient.addColorStop(1, '#00cc6a');

                    ctx.fillStyle = gradient;
                    ctx.beginPath();
                    ctx.roundRect(x + 1, y + 1, gridSize - 2, gridSize - 2, 8);
                    ctx.fill();

                    // Eyes
                    ctx.fillStyle = '#1a1a2e';
                    if(dx === 1) { // moving right
                        ctx.beginPath(); ctx.arc(x + 14, y + 7, 3, 0, Math.PI*2); ctx.fill();
                        ctx.beginPath(); ctx.arc(x + 14, y + 13, 3, 0, Math.PI*2); ctx.fill();
                    } else if(dx === -1) { // left
                        ctx.beginPath(); ctx.arc(x + 6, y + 7, 3, 0, Math.PI*2); ctx.fill();
                        ctx.beginPath(); ctx.arc(x + 6, y + 13, 3, 0, Math.PI*2); ctx.fill();
                    } else if(dy === -1) { // up
                        ctx.beginPath(); ctx.arc(x + 7, y + 6, 3, 0, Math.PI*2); ctx.fill();
                        ctx.beginPath(); ctx.arc(x + 13, y + 6, 3, 0, Math.PI*2); ctx.fill();
                    } else { // down
                        ctx.beginPath(); ctx.arc(x + 7, y + 14, 3, 0, Math.PI*2); ctx.fill();
                        ctx.beginPath(); ctx.arc(x + 13, y + 14, 3, 0, Math.PI*2); ctx.fill();
                    }
                } else {
                    // Body
                    const alpha = 1 - (index / snake.length) * 0.6;
                    gradient.addColorStop(0, `rgba(0, 255, 136, ${alpha})`);
                    gradient.addColorStop(1, `rgba(0, 200, 100, ${alpha})`);

                    ctx.fillStyle = gradient;
                    ctx.beginPath();
                    ctx.roundRect(x + 2, y + 2, gridSize - 4, gridSize - 4, 6);
                    ctx.fill();
                }
            });
        }

        // Move snake
        function moveSnake() {
            const head = {x: snake[0].x + dx, y: snake[0].y + dy};

            // Wrap around
            if(head.x < 0) head.x = tileCountX - 1;
            if(head.x >= tileCountX) head.x = 0;
            if(head.y < 0) head.y = tileCountY - 1;
            if(head.y >= tileCountY) head.y = 0;

            snake.pop();
            snake.unshift(head);
        }

        // Game loop
        function gameLoop(timestamp) {
            if(timestamp - lastTime > speed) {
                ctx.clearRect(0, 0, canvas.width, canvas.height);
                drawGrid();
                moveSnake();
                drawSnake();
                lastTime = timestamp;
            }
            requestAnimationFrame(gameLoop);
        }

        // Controls
        document.addEventListener('keydown', (e) => {
            switch(e.key) {
                case 'ArrowUp':
                    if(dy === 0) { dx = 0; dy = -1; }
                    break;
                case 'ArrowDown':
                    if(dy === 0) { dx = 0; dy = 1; }
                    break;
                case 'ArrowLeft':
                    if(dx === 0) { dx = -1; dy = 0; }
                    break;
                case 'ArrowRight':
                    if(dx === 0) { dx = 1; dy = 0; }
                    break;
            }
        });

        requestAnimationFrame(gameLoop);
    </script>
</body>
</html>
```

این کد یک صفحه HTML کامل است که:
- یک canvas 800x600 با پس‌زمینه تیره و گرید سبز کم‌رنگ دارد
- یک مار 5 تایی با سر سبز روشن و بدن با گرادیان دارد
- چشم‌هایی که جهت حرکت را نشان می‌دهند
- مار به صورت خودکار به سمت راست حرکت می‌کند (مستقیم)
- وقتی به دیوار می‌رسد، از طرف دیگر ظاهر می‌شود ( wrap around )
- با کلیدهای جهت‌نما می‌توان جهت حرکت را تغییر داد
- انیمیشن نرم با requestAnimationFrame

